// Canadian provinces and territories
case "AB": "Alberta" case "BC": "British Columbia" case "MB": "Manitoba" case "NB": "New Brunswick" case "NF": "Newfoundland" case "NS": "Nova Scotia" case "NT": "Northwest Territories" case "NU": "Nunavut" case "ON": "Ontario" case "PE": "Prince Edward Island" case "QC", "PQ": "Québec" case "SK": "Saskatchewan" case "YT": "Yukon Territory"
default: abbreviation; ) else abbreviation;

