//cdIncreaseCurrencyByAPercentage

Function (CurrencyVar valueToIncrease, NumberVar percentIncrease)

valueToIncrease + valueToIncrease * percentIncrease / 100;

//cdIncreaseNumberByAPercentage

Function (NumberVar valueToIncrease, NumberVar percentIncrease)

valueToIncrease + valueToIncrease * percentIncrease / 100;

Function (NumberVar nWorkingDays, DateTimeVar startDateTime)
    //the result = startDateTime + nWorkingDays + nHolidays (including weekends)
    //the algorithm below also works when nWorkingDays is negative

    DateTimeVar ResultFunction;
    NumberVar totalDays;
    //give a rough estimate for total days. For each 5 work days there are 7
    //days. Also add in an extra 2 weekend days to account for a partial week.
    totalDays := Fix(nWorkingDays * 7 / 5 + 1) + 2;

    NumberVar iteratedDiff;
    iteratedDiff := cdDateDiffSkipHolidays (startDateTime, startDateTime + totalDays);

    If (iteratedDiff >= nWorkingDays) Then
       ( 
        While iteratedDiff >= nWorkingDays Do
            (
            totalDays := totalDays - 1;
            iteratedDiff := cdDateDiffSkipHolidays (startDateTime, startDateTime + totalDays);
            );
        ResultFunction := startDateTime + totalDays + 1;
        )
    Else 
        (
        While iteratedDiff < nWorkingDays Do
            (
            totalDays := totalDays + 1;
            iteratedDiff := cdDateDiffSkipHolidays (startDateTime, startDateTime + totalDays);
            );
        ResultFunction := startDateTime + totalDays;
        );         
    ResultFunction;

Function (NumberVar nNonWeekendDays, DateTimeVar startDateTime)

    //the result = startDateTime + nNonWeekendDays + nWeekendDays
    //the algorithm below also works when nNonWeekendDays is negative

    DateTimeVar ResultFunction;
    NumberVar totalDays;
    //'give a rough upper bound for total days. For each 5 non weekend days there are 7
    //'days. Also add in an extra 2 weekend days to account for a partial week.
    totalDays := Fix(nNonWeekendDays * 7 / 5 + 1) + 2;

    While cdDateDiffSkipWeekends (startDateTime, startDateTime + totalDays) >= nNonWeekendDays Do
        (
        totalDays := totalDays - 1;
        );

    ResultFunction := startDateTime + totalDays + 1;

Function (DateTimeVar startDateTime, DateTimeVar endDateTime)

    NumberVar ResultFunction;
    BooleanVar reversed;
    reversed := False;

    If startDateTime > endDateTime Then
        (
        DateTimeVar tempDateTime;
        tempDateTime := startDateTime;
        startDateTime := endDateTime;
        endDateTime := tempDateTime;
        reversed := True;
        );

    NumberVar diffWithoutWeekends;
    diffWithoutWeekends := cdDateDiffSkipWeekends (startDateTime, endDateTime);

    NumberVar startYear;
    NumberVar endYear;
    startYear := Year (startDateTime);
    endYear := Year (endDateTime);

    DateVar Array statsInStartYear;
    statsInStartYear := cdStatutoryHolidays (startYear, True);

    DateVar Range dateRange;
    dateRange := CDate (startDateTime) To CDate (endDateTime);

    NumberVar numberOfStatsInRange;
    numberOfStatsInRange := 0;

    //'We are assuming that the number of statutory holidays in a year is always the same
    NumberVar numberOfStatsInOneYear;
    numberOfStatsInOneYear := UBound (statsInStartYear);

    NumberVar i;

    For i := 1 To numberOfStatsInOneYear Do
        (
        If (statsInStartYear[i] In dateRange) Then
            numberOfStatsInRange := numberOfStatsInRange + 1;
        );

    If startYear <> endYear Then
        (  
        DateVar Array statsInEndYear;
        statsInEndYear := cdStatutoryHolidays (endYear, True);

        For i := 1 To numberOfStatsInOneYear Do
            (
            If statsInEndYear[i] In dateRange Then
                numberOfStatsInRange := numberOfStatsInRange + 1;
            );

        numberOfStatsInRange := numberOfStatsInRange + (endYear - startYear - 1) * numberOfStatsInOneYear;
        );

    ResultFunction := diffWithoutWeekends - numberOfStatsInRange;

    //Can happen in rare situations e.g. The difference between Friday March 28 (Good Friday)
    //and Saturday March 29 is -1 at this point.
    If ResultFunction < 0 Then ResultFunction := 0;

    If reversed Then ResultFunction := -ResultFunction;
    ResultFunction;

Function (DateTimeVar startDateTime, DateTimeVar endDateTime)

    //this function assumes that weekends are on Saturday and Sunday. You can modify the constants
    //below to change this assumption.
    NumberVar ResultFunction;
    ResultFunction := 
        DateDiff("d", startDateTime, endDateTime) - 
        DateDiff("ww", startDateTime, endDateTime, crSaturday) - 
        DateDiff("ww", startDateTime, endDateTime, crSunday);

Function (stringVar regionAbbreviation, Optional stringVar country := "USA")
select UpperCase (country)
case "CANADA": cdExpandRegionAbbreviationCanada (regionAbbreviation) Case "USA", "U.S.A.", "US", "U.S.", "UNITED STATES", "UNITED STATES OF AMERICA": cdExpandRegionAbbreviationUSA (regionAbbreviation) default: regionAbbreviation;

Function (Optional DateTimeVar dayInQuarter := CurrentDate)
NumberVar y; y := Year (dayInQuarter);
Select DatePart ("q", dayInQuarter) Case 1: CDate (y, 1, 1) Case 2: CDate (y, 4, 1) Case 3: CDate (y, 7, 1) Case 4: CDate (y, 10, 1);

Function (CurrencyVar value, NumberVar nDecimalPlaces, StringVar thousandsSymbol, StringVar millionsSymbol)

    nDecimalPlaces := Round (nDecimalPlaces);
    If (nDecimalPlaces < 0 Or nDecimalPlaces > 9) Then
        nDecimalPlaces := 2;

    If Abs (value) >= 1000000 Then
       CStr (value / 1000000, nDecimalPlaces) + millionsSymbol
    Else
       (
       If Abs (value) >= 1000 Then
          CStr (value / 1000, nDecimalPlaces) + thousandsSymbol
       Else
          CStr (value, nDecimalPlaces);
       );

Function (NumberVar value, NumberVar nDecimalPlaces, StringVar thousandsSymbol, StringVar millionsSymbol)

    nDecimalPlaces := Round (nDecimalPlaces);
    If (nDecimalPlaces < 0 Or nDecimalPlaces > 9) Then
        nDecimalPlaces := 2;

    If Abs (value) >= 1000000 Then
       CStr (value / 1000000, nDecimalPlaces) + millionsSymbol
    Else
       ( 
       If Abs (value) >= 1000 Then
          CStr (value / 1000, nDecimalPlaces) + thousandsSymbol
       Else
          CStr (value, nDecimalPlaces);
       );

Function (Optional DateTimeVar dayInQuarter := CurrentDate)
NumberVar y; y := Year (dayInQuarter);
Select DatePart ("q", dayInQuarter) Case 1: CDate (y, 3, 31) Case 2: CDate (y, 6, 30) Case 3: CDate (y, 9, 30) Case 4: CDate (y, 12, 31);

Function (NumberVar y, Optional BooleanVar asRecognized := False) //returns a Date array

    DateVar Array holidays; // [10];
    Redim Holidays [10];
    DateVar Array ResultFunction; // [10];
    Redim ResultFunction [10];

    DateVar d;
    NumberVar offset;
    NumberVar officialDay;

    //New Year's day is January 1
    d := CDate (y, 1, 1);
    If asRecognized Then
       (
        officialDay := WeekDay (d);
        Select officialDay
        Case 1: //Sunday
            d := d + 1
        Case 7: //Saturday
            d := d + 2; 
       );        

    holidays [1] := d;

    //Good Friday is the Friday before Easter Sunday
    holidays [2] := cdEasterDate (y) - 2;

    //Since 1952 Victoria day is the Monday prior to May 25
    d := CDate (y, 5, 25);
    offset := WeekDay (d, crMonday) - 1;
    holidays [3] := d - offset;

    //Canada Day is July 1
    d := CDate (y, 7, 1);
    If asRecognized Then
       ( 
        officialDay := WeekDay (d);
        Select officialDay
        Case 1: //Sunday
            d := d + 1
        Case 7: //Saturday
            d := d + 2; 
       );      
    holidays [4] := d;

    //BC day is the first Monday of August
    d := CDate (y, 8, 1);
    offset := (7 - WeekDay (d, crTuesday)) Mod 7;
    holidays [5] := d + offset;

    //Since 1894 Labour day is the first Monday of September
    d := CDate (y, 9, 1);
    offset := (7 - WeekDay (d, crTuesday)) Mod 7;
    holidays [6] := d + offset;

    //Since 1957 Thanksgiving day is the second Monday of October
    d := CDate (y, 10, 1);
    offset := 7 + (7 - WeekDay (d, crTuesday)) Mod 7;
    holidays [7] := d + offset;

    //Remembrance day is November 11
    d := CDate (y, 11, 11);
    If asRecognized Then
       ( 
        officialDay := WeekDay (d);
        Select officialDay
        Case 1: //Sunday
            d := d + 1
        Case 7: //Saturday
            d := d + 2; 
       );        
    holidays [8] := d;

    //Christmas day is December 25
    d := CDate (y, 12, 25);
    If asRecognized Then
       ( 
        officialDay := WeekDay (d);
        Select officialDay
        Case 1: //Sunday
            d := d + 1
        Case 7: //Saturday
            d := d + 2; 
       );   
    holidays [9] := d;

    //Boxing day is December 26
    d := CDate (y, 12, 26);
    If asRecognized Then
       ( 
        officialDay := WeekDay (d);
        Select officialDay
        Case 1: //Sunday. Christmas day will be recognized on Monday, so Boxing Day is recognized on Tuesday
            d := d + 2
        Case 7: //Saturday
            d := d + 2; 
       );        
    holidays [10] := d;

    ResultFunction := holidays;

Function (NumberVar y)

// EASTER DATE CALCULATION FOR YEARS 1583 TO 4099

// y is a 4 digit year 1583 to 4099
// d returns the day of the month of Easter
// m returns the month of Easter

// Easter Sunday is the Sunday following the Paschal Full Moon
// (PFM) date for the year

// This algorithm is an arithmetic interpretation of the 3 step
// Easter Dating Method developed by Ron Mallen 1985, as a vast
// improvement on the method described in the Common Prayer Book

// Because this algorithm is a direct translation of the
// official tables, it can be easily proved to be 100% correct

// This algorithm derives values by sequential inter-dependent
// calculations, so ... DO NOT MODIFY THE ORDER OF CALCULATIONS!

// The \ operator may be unfamiliar - it means integer division
// for example, 30 \ 7 = 4 (the remainder is ignored)

// All variables are integer data types

// It's free!  Please do not modify code or comments!
// ==========================================================

    DateVar ResultFunction;
    NumberVar FirstDig;             //intermediate results
    NumberVar Remain19;             //intermediate results
    NumberVar temp;                 //intermediate results
    NumberVar tA;                   //table A to E results
    NumberVar tB;
    NumberVar tC;
    NumberVar tD;
    NumberVar tE;          
    NumberVar m;
    NumberVar d;

    FirstDig := y \ 100;            //first 2 digits of year
    Remain19 := y Mod 19;           //remainder of year / 19

    //calculate PFM date
    temp := (FirstDig - 15) \ 2 + 202 - 11 * Remain19;
    If FirstDig > 26 Then temp := temp - 1;
    If FirstDig > 38 Then temp := temp - 1;

    //this next line uses underscore (_) line continuation characters
    //in older versions of VB you may need to revert to one long line
    If ((FirstDig = 21) Or (FirstDig = 24) Or (FirstDig = 25)Or (FirstDig = 33) Or (FirstDig = 36) Or (FirstDig = 37)) Then 
       temp := temp - 1;

    temp := temp Mod 30;

    tA := temp + 21;
    If temp = 29 Then tA := tA - 1;
    If (temp = 28 And Remain19 > 10) Then tA := tA - 1;

    //find the next Sunday
    tB := (tA - 19) Mod 7;

    tC := (40 - FirstDig) Mod 4;
    If tC = 3 Then tC := tC + 1;
    If tC > 1 Then tC := tC + 1;

    temp := y Mod 100;
    tD := (temp + temp \ 4) Mod 7;

    tE := ((20 - tB - tC - tD) Mod 7) + 1;
    d := tA + tE;

    //return the date
    If d > 31 Then
        (
        d := d - 31;
        m := 4;
        )
    Else
        m := 3;

    ResultFunction := DateValue(y, m, d);

Function (NumberVar timeInterval, StringVar baseUnit, StringVar roundTo, StringVar daysSymbol, StringVar hoursSymbol, StringVar minutesSymbol)

    StringVar ResultFunction;
    //ensure that baseUnit is one of: days, hours
    baseUnit := LCase (baseUnit);
    If Not (baseUnit In ["days", "hours"]) Then
        baseUnit := "days";

    //ensure that roundTo is one of: days, hours or minutes
    roundTo := LCase (roundTo);
    If Not (roundTo In ["days", "hours", "minutes"]) Then
        roundTo := "minutes";

    //ensure that baseUnit is not finer grained than roundTo
    If roundTo = "days" Then
        baseUnit := "days";

    NumberVar days;
    NumberVar hours;
    NumberVar minutes;
    NumberVar timeRemaining;
    NumberVar signOfResult;

    signOfResult := sgn (timeInterval);
    timeInterval := abs (timeInterval);

    Select roundTo

    Case "days":
        (   
        days := Round (timeInterval);
        If (days = 1 And Trim (daysSymbol) = "days") Then
            daysSymbol := Replace (daysSymbol, "s", "");

        ResultFunction := CStr (days, 0) & daysSymbol;
        )
    Case "hours":
        (
        If baseUnit = "days" Then
            (     
            //timeRemaining in fractional days  
            timeRemaining := timeInterval;
            days := Int (timeRemaining);

            //timeRemaining in hours
            timeRemaining := (timeRemaining - days) * 24;
            hours := Round (timeRemaining);

            //handle rounding to the nearest hour
            If hours = 24 Then
                (
                days := days + 1;
                hours := 0;
                );
            ResultFunction := CStr (days, 0) & daysSymbol & CStr (hours, 0) & hoursSymbol;
            )
        Else
            (
            hours := Round (timeInterval * 24);
            If hours = 1 Then
                (
                If Trim (hoursSymbol) In ["hrs", "hours"] Then
                    hoursSymbol := Replace (hoursSymbol, "s", "");
                );

            ResultFunction := CStr (hours, 0) & hoursSymbol;
            );
        ) // End Case "hours"

    Case "minutes":
        (
        If baseUnit = "days" Then
            (
            //timeRemaining in fractional days  
            timeRemaining := timeInterval;
            days := Int (timeRemaining);

            //timeRemaining in fractional hours
            timeRemaining := (timeRemaining - days) * 24; 
            hours := Int (timeRemaining);

            //timeRemaining is fractional minutes
            timeRemaining := (timeRemaining - hours) * 60; 
            minutes := Round (timeRemaining);

            //handle rounding to the nearest minute
            //for example, 2d 23h 60m is rounded to 3d 0h 0m
            If minutes = 60 Then
                (
                hours := hours + 1;
                minutes := 0;
                If hours = 24 Then
                    (            
                    days := days + 1;
                    hours := 0;
                    );
                );

            ResultFunction := CStr (days, 0) & daysSymbol & CStr (hours, 0) & hoursSymbol & CStr (minutes, 0) & minutesSymbol
            )
        Else
            (
            If baseUnit = "hours" Then
               (
               //timeRemaining in fractional hours
               timeRemaining := timeInterval * 24; 
               hours := Int (timeRemaining);

               //timeRemaining is fractional minutes
               timeRemaining := (timeRemaining - hours) * 60; 
               minutes := Round (timeRemaining);

               //handle rounding to the nearest minute
               //For example, 23h 60m is rounded to 24h 0m
               If minutes = 60 Then
                   (
                   hours := hours + 1;
                   minutes := 0;
                   );

               ResultFunction := CStr (hours, 0) & hoursSymbol & CStr (minutes, 0) & minutesSymbol;
               );
            ); // End Else        
        ); //End Case "minutes" = End Select


    If (days = 1 And Trim (daysSymbol) = "days") Then
         ResultFunction := Replace (ResultFunction, "days", "day");

    If hours = 1 Then
       (
        Select Trim (hoursSymbol)
        Case "hours":
            ResultFunction := Replace (ResultFunction, "hours", "hour")
        Case "hrs":
            ResultFunction := Replace (ResultFunction, "hrs", "hr");
        );

    If minutes = 1 Then
        (
        Select Trim (minutesSymbol)
        Case "minutes":
            ResultFunction := Replace (ResultFunction, "minutes", "minute")
        Case "mins":
            ResultFunction := Replace (ResultFunction, "mins", "min");
        );

    If signOfResult = -1 Then
        ResultFunction := "- " + ResultFunction;

    ResultFunction;
